16	const (
17		// factsBackendLocalGitmeta is a bare, on-disk git-meta store under the
18		// plugin cache; fully local, no network/entiredb/Postgres. Default on
19		// unconnected repos.
20		factsBackendLocalGitmeta = "local-gitmeta"
21		// factsBackendHTTP drives the hosted per-fact wire (factsync perfact.go).
22		// Default on connected repos.
23		factsBackendHTTP = "http"
24		// envFactsBackend selects the backend when --memories-backend is unset.
25		envFactsBackend = "ENTIRE_BRAIN_FACTS_BACKEND"
26	)
27	
28	// factsSyncOptions bundles the flag state for `facts sync`.
29	type factsSyncOptions struct {
30		branch  string
31		backend string
32		member  string
33		// http backend only (mirror publish's flag/env resolution):
34		apiURL string
35		token  string
36		repoID string
37	
38		jsonOut bool
39	}
40	
41	func newFactsSyncCommand(opts Options) *cobra.Command {
42		var syncOpts factsSyncOptions
43		cmd := &cobra.Command{
44			Use:   "sync",
45			Short: "Sync this branch's local memories with the shared memory set",
46			Long: `sync exchanges this branch's local memories with the shared memory set.
47	
48	The default backend depends on connectedness. On a repo connected to Brainstore
49	('` + brainInvocation(os.LookupEnv, "connect") + `'), a plain sync uses the hosted per-fact wire: push this
50	branch's memories, pull the team's delta feed — the same exchange the background
51	sync runs, except failures fail the command instead of degrading silently. On an
52	unconnected repo, a plain sync uses the fully local git-meta store and never
53	leaves the machine. ENTIRE_BRAIN_NO_EGRESS (or its deprecated alias
54	ENTIRE_BRAIN_LOCAL_ONLY) suppresses hosted sync regardless of defaults and
55	flags; a connected repo's plain sync is then skipped, loudly.
56	
57	Backends (--memories-backend, or ` + envFactsBackend + `):
58	  local-gitmeta  a bare, on-disk git-meta store under the brain cache
59	                 (<cache>/brain/<repo-key>/gitmeta.git); fully local, no network,
60	                 entiredb, or Postgres. Default on unconnected repos.
61	  http           the hosted per-fact wire, explicitly. Default on connected
62	                 repos. Target resolves flag > env > connected binding:
63	                 --api-url/ENTIRE_API_URL, --repo-id/ENTIRE_REPO_ID,
64	                 --token/ENTIRE_API_TOKEN; on a connected repo the binding
65	                 supplies the target and the token is minted automatically.`,
66			Args: cobra.NoArgs,
67			RunE: func(cmd *cobra.Command, args []string) error {
68				return runFactsSync(cmd, opts, syncOpts)
69			},
70		}
71		cmd.Flags().StringVar(&syncOpts.branch, "branch", "", "Branch to sync (default: current branch)")
72		cmd.Flags().StringVar(&syncOpts.backend, "memories-backend", "", "Memory-set backend: local-gitmeta or http (default: http on a connected repo, else local-gitmeta)")
73		cmd.Flags().StringVar(&syncOpts.member, "member", "", "Member identity stamped on queued review proposals (default: git user.email)")
74		cmd.Flags().StringVar(&syncOpts.repoID, "repo-id", "", "Target repo id for the http backend (overrides ENTIRE_REPO_ID)")
75		cmd.Flags().StringVar(&syncOpts.apiURL, "api-url", "", "Entire API base URL for the http backend, https:// (overrides ENTIRE_API_URL)")
76		cmd.Flags().StringVar(&syncOpts.token, "token", "", "Entire API bearer token for the http backend (overrides ENTIRE_API_TOKEN)")
77		cmd.Flags().BoolVar(&syncOpts.jsonOut, "json", false, "Emit the sync result as JSON")
78		// --facts-backend predates the facts→memories rename; keep it working.
79		legacyFlagAlias(cmd.Flags(), "facts-backend", "memories-backend")
80		return cmd
81	}
82	
83	func runFactsSync(cmd *cobra.Command, opts Options, syncOpts factsSyncOptions) error {
84		ctx := cmd.Context()
85	
86		repoDir, local, err := resolveLocalTargetRepoDir(ctx, opts.Runner, agentSurfaceTarget(opts, nil))
87		if err != nil {
88			return err
89		}
90		if !local {
91			return fmt.Errorf("memories sync requires a local repository path")
92		}
93		storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
94		if err != nil {
95			return err
96		}
97	
98		branch := strings.TrimSpace(syncOpts.branch)
99		if branch == "" {
100			if current, gitErr := gitScalar(ctx, opts.Runner, repoDir, "branch", "--show-current"); gitErr == nil {
101				branch = strings.TrimSpace(current)
102			}
103		}
104		if branch == "" {
105			branch = distillDefaultBranch
106		}
107	
108		backend := resolveFactsBackendName(syncOpts.backend)
109		if backend == "" {
110			// No explicit backend: connectedness decides. Connect was the consent
111			// moment (ADR-P1-A reconciliation, COR-2233), so a connected repo syncs
112			// hosted by default; the no-egress kill switch still always wins and
113			// falls back to the local store, loudly.
114			binding, present, bindErr := readHostedRepoBinding(storage.BrainDir)
115			connected := bindErr == nil && present && !binding.OptedOut
116			if bindErr != nil {
117				fmt.Fprintf(cmd.ErrOrStderr(), "warning: hosted binding unreadable (syncing locally; run '%s' to rebind): %v\n", brainInvocation(os.LookupEnv, "connect"), bindErr)
118			}
119			switch {
120			case connected && !brainNoEgressMode():
121				return runHostedFactsSync(cmd, opts, syncOpts, repoDir, storage, branch)
122			case connected:
123				// Do NOT fall back to the local git-meta store here: on a connected
124				// repo its head is stale (the per-fact wire has been the sync path
125				// since connect), and a keep-both merge against a stale head
126				// re-raises every deferred per-fact conflict into the local review
127				// queue. The kill switch suppresses sync; it does not redirect it.
128				fmt.Fprintf(cmd.OutOrStdout(), "memories sync: skipped: %s is set and this repo is connected to Brainstore; unset it to sync, or pass --memories-backend=local-gitmeta to use the local git-meta store\n", noEgressToggleName())
129				return nil
130			}
131			backend = factsBackendLocalGitmeta
132		}
133	
134		switch backend {
135		case factsBackendHTTP:
136			// The master kill switch always wins over the hosted opt-in.
137			if brainNoEgressMode() {
138				return fmt.Errorf("no_egress: hosted memory sync is disabled while %s is set; unset it or use --memories-backend=local-gitmeta", noEgressToggleName())
139			}
140			return runHostedFactsSync(cmd, opts, syncOpts, repoDir, storage, branch)
141		case factsBackendLocalGitmeta:
142		default:
143			return fmt.Errorf("unknown --memories-backend %q (want %q or %q)", backend, factsBackendLocalGitmeta, factsBackendHTTP)
144		}
145	
146		facts, err := loadFacts(storage.BrainDir, branch)
147		if err != nil {
148			return err
149		}
150		memberID := resolveSyncMemberID(ctx, opts.Runner, repoDir, syncOpts.member)
151	
152		gitDir, err := gitmetaDirForKey(opts.Env, storage.Key)
153		if err != nil {
154			return err
155		}
156		srv, err := factgitmeta.NewLocalBackend(gitDir, storage.Key, opts.Now)
157		if err != nil {
158			return err
159		}
160		backendLabel := "local-gitmeta (" + gitDir + ")"
161	
162		// The merge runs on this runner (ADR-P1-E); the backend only stores the blob
163		// and CAS-swaps the head. Sync retries on a losing swap and never drops a
164		// member's fact.
165		res, err := factsync.Sync(ctx, srv, storage.Key, branch, memberID, facts, opts.Now().UTC())
166		if err != nil {
167			return err
168		}
169	
170		if err := persistFactsSyncProposals(storage.BrainDir, branch, res.Proposals); err != nil {
171			return err
172		}
173	
174		if syncOpts.jsonOut {
175			return writeJSON(cmd, map[string]any{
176				"branch":    branch,
177				"backend":   backendLabel,
178				"member":    memberID,
179				"published": res.Published,
180				"ref":       res.NewRef,
181				"attempts":  res.Attempts,
182				"proposals": res.Proposals,
183				"facts":     len(facts),
184			})
185		}
186	
187		out := cmd.OutOrStdout()
188		if res.Published {
189			fmt.Fprintf(out, "synced %d local memory(ies) on %s via %s: head advanced to %s (%d attempt(s))\n",
190				len(facts), branch, backendLabel, res.NewRef, res.Attempts)
191		} else {
192			fmt.Fprintf(out, "synced %d local memory(ies) on %s via %s: no change; head at %s (%d attempt(s))\n",
193				len(facts), branch, backendLabel, refOrNone(res.NewRef), res.Attempts)
194		}
195		if len(res.Proposals) > 0 {
196			fmt.Fprintf(out, "%d conflict(s) queued for review ('memories review'):\n", len(res.Proposals))
197			for _, p := range res.Proposals {
198				fmt.Fprintf(out, "  %s %s -> %s (by %s, confidence %.2f)\n", p.Action, p.CandidateID, p.TargetID, p.ProposedBy, p.Confidence)
199			}
200		}
201		return nil
202	}
203	
204	// runHostedFactsSync is the manual flavor of hostedFactsSyncAndPull: the same
205	// per-fact exchange (batch-upsert this branch's store, pull the repo delta
206	// feed, rebuild the branch store), but the user explicitly asked for this
207	// sync, so failures surface in the exit code and output instead of degrading
208	// to a stderr note (COR-2202 precedent).
209	func runHostedFactsSync(cmd *cobra.Command, opts Options, syncOpts factsSyncOptions, repoDir string, storage repoStorage, branch string) error {
210		ctx := cmd.Context()
211		errW := cmd.ErrOrStderr()
212		target, err := resolveManualHostedTarget(ctx, opts, storage.BrainDir, repoDir, "memories sync", syncOpts.repoID, syncOpts.apiURL, syncOpts.token)
213		if err != nil {
214			return err
215		}
216		srv := &factsync.HTTPServer{BaseURL: target.baseURL, Token: target.token}
217		backendLabel := "hosted (" + strings.TrimRight(target.baseURL, "/") + ")"
218	
219		counts, skipped, pushErr := pushHostedFacts(ctx, storage, srv, target.repoID, branch)
220		if skipped > 0 {
221			fmt.Fprintf(errW, "warning: skipped %d unpublishable record(s) whose content id does not re-derive (kept locally, not uploaded)\n", skipped)
222		}
223		// The pull runs even after a failed push: the team's memories still land,
224		// and the error below reports exactly which half failed.
225		kept, total, manifestErr, pullErr := pullHostedFacts(ctx, opts, repoDir, storage, srv, target.repoID, target.baseURL, target.token, branch)
226		if pushErr == nil && pullErr == nil {
227			// Both halves completed: record the per-branch marker, same rule as the
228			// background sync (the blind-spot note keys off its absence).
229			if err := writeHostedFactsBinding(storage.BrainDir, branch, target.repoID, target.baseURL); err != nil {
230				return fmt.Errorf("memories sync: record hosted target: %w", err)
231			}
232		}
233		if manifestErr != nil {
234			fmt.Fprintf(errW, "warning: memories updated, but the source manifest could not be refreshed: %v\n", manifestErr)
235		}
236		switch {
237		case pushErr != nil && pullErr != nil:
238			return fmt.Errorf("memories sync: push to %s failed: %v; pull failed: %v", backendLabel, pushErr, pullErr)
239		case pushErr != nil:
240			return fmt.Errorf("memories sync: pulled %d memory(ies) from %s (%d kept), but the push failed (local brain unaffected): %w", total, backendLabel, kept, pushErr)
241		case pullErr != nil:
242			return fmt.Errorf("memories sync: pushed %d memory(ies) to %s, but the pull failed (local brain unaffected): %w", counts.Added+counts.Changed+counts.Unchanged, backendLabel, pullErr)
243		}
244	
245		if syncOpts.jsonOut {
246			return writeJSON(cmd, map[string]any{
247				"branch":                branch,
248				"backend":               backendLabel,
249				"pushed_added":          counts.Added,
250				"pushed_changed":        counts.Changed,
251				"pushed_unchanged":      counts.Unchanged,
252				"skipped_unpublishable": skipped,
253				"feed_facts":            total,
254				"feed_kept":             kept,
255			})
256		}
257		fmt.Fprintf(cmd.OutOrStdout(), "synced %s via %s: pushed added=%d changed=%d unchanged=%d; feed facts=%d kept=%d\n",
258			branch, backendLabel, counts.Added, counts.Changed, counts.Unchanged, total, kept)
259		return nil
260	}
261	
262	// persistFactsSyncProposals appends conflicts the merge raised to the same
263	// durable queue consumed by facts review/status and the recall pending-review
264	// guard. The brain write lock makes the read-merge-write atomic with other
265	// local writers, while writeFactProposals supplies stable ordering and
266	// deduplication.
267	func persistFactsSyncProposals(brainDir, branch string, proposals []factProposal) error {
268		if len(proposals) == 0 {
269			return nil
270		}
271		return withBrainWriteLock(brainDir, func() error {
272			existing, err := loadFactProposals(brainDir, branch)
273			if err != nil {
274				return fmt.Errorf("memories sync: load review queue: %w", err)
275			}
276			if err := writeFactProposals(brainDir, branch, append(existing, proposals...)); err != nil {
277				return fmt.Errorf("memories sync: persist review queue: %w", err)
278			}
279			return nil
280		})
281	}
282	
283	// resolveFactsBackendName folds the --memories-backend flag and the env
284	// override into an explicit backend name. Empty means "no explicit choice":
285	// the caller defaults by connectedness (hosted on a connected repo, else
286	// local-gitmeta).
287	func resolveFactsBackendName(flagVal string) string {
288		if v := strings.TrimSpace(flagVal); v != "" {
289			return v
290		}
291		return strings.TrimSpace(os.Getenv(envFactsBackend))
292	}
293	
294	// resolveSyncMemberID derives the member identity stamped on queued review
295	// proposals: the explicit --member, else the repo's git user.email, else
296	// $USER@<hostname>, else "local". A non-empty id is required (Sync rejects "").
297	func resolveSyncMemberID(ctx context.Context, runner CommandRunner, repoDir, override string) string {
298		if v := strings.TrimSpace(override); v != "" {
299			return v
300		}
301		if email, err := gitScalar(ctx, runner, repoDir, "config", "--get", "user.email"); err == nil {
302			if e := strings.TrimSpace(email); e != "" {
303				return e
304			}
305		}
306		if u := strings.TrimSpace(os.Getenv("USER")); u != "" {
307			if host, err := os.Hostname(); err == nil && host != "" {
308				return u + "@" + host
309			}
310			return u
311		}
312		return "local"
313	}
314	
315	// gitmetaDirForKey resolves the local git-meta store path for a repo key
316	// (<cache>/brain/<key>/gitmeta.git), mirroring brainDirForKey's key handling but
317	// rooted in the plugin CACHE tree (the store is a local, rebuildable sync
318	// staging area, not authoritative brain data).
319	func gitmetaDirForKey(env EntireEnv, key string) (string, error) {
320		if first, _, _ := strings.Cut(key, "/"); first == workspaceDirName {
321			return "", fmt.Errorf("repo key uses the reserved %q segment: %s", workspaceDirName, key)
322		}
323		dirs, err := resolvePluginDirs(env)
324		if err != nil {
325			return "", err
326		}
327		root := filepath.Join(dirs.Cache, "brain")
328		if err := rejectBrainRootPathSymlinks(root, filepath.FromSlash(key)); err != nil {
329			return "", err
330		}
331		return filepath.Join(root, filepath.FromSlash(key), "gitmeta.git"), nil
332	}
333	
334	// refOrNone renders an empty ref as "(none)" for the no-change/empty case.
335	func refOrNone(ref string) string {
336		if ref == "" {
337			return "(none)"
338		}
339		return ref
340	}
