// Package factgitmeta stores git-meta project records inside a bare, on-disk
// git repository under the plugin cache, compare-and-swapping a single ref
// through the git-meta engine plus a filesystem ref CAS. Its one consumer is
// the entity index (internal/entityindex), which keeps its windows and state
// as records in this store. The package once also implemented the
// factsync.Server seam for the local fact-set sync backend; that backend was
// removed (COR-2236), and fact-set refs left behind in existing stores are
// never read again.
package factgitmeta

// metaRef is the single git ref the local git-meta head lives on. The upstream
// `git meta` CLI serializes to refs/meta/<remote>/main (golden_test resolves
// refs/meta/local/main); we reuse that local ref name to mirror the reference
// layout while staying unmistakably local-only.
const metaRef = "refs/meta/local/main"

// maxRefCASRetries bounds the ref-level compare-and-swap retry loop. A lost ref
// race (another writer advanced refs/meta between our read and write) is
// mechanical and retried; exhaustion surfaces to the caller, never a silent
// drop.
const maxRefCASRetries = 5

